// ─────────────────────────────────────────────────────────────────────────────────────────────
// Bloques con comportamiento v1.2 · game.bloques
//
// El comportamiento cuelga del MATERIAL, no del voxel. Es como lo hace Minecraft: el mundo guarda
// un id de paleta por celda y el comportamiento vive en UN objeto por TIPO de bloque; el codigo de
// movimiento pregunta «que bloque toco» y lo resuelve con un indice de array (O(1), sin recorrer
// nada). Un script por voxel serian 96x48x96 = 442368 closures, que es justo lo que Minecraft evita.
//
// Se engancha en UN solo sitio: un envoltorio sobre mcUpdate (app.js:5053), que tiene una unica
// llamada (mcTick, app.js:6323). NO se toca mcSolid: lo usan tambien el mallado (app.js:4711), el
// raycast (5529) y romper/poner (5658), asi que hacer la escalera atravesable se veria por las
// caras de los vecinos y cambiaria el apuntado. La escalera es solida: subes PEGADO a ella.
//
// Uso:
//   game.bloques.define('hab:escalera', { trepable:true, subida:4, bajada:5 });
//   game.bloques.define('hab:placa',    { alPisar(c){ game.tp(51,20,50); } });
//   game.bloques.info()    ← que piso / que tengo delante, con la CLAVE EXACTA para copiar
//   game.bloques.lista()   game.bloques.quitar(clave)   game.bloques.avisos()
//   game.bloques.pasoSuave(0.06)  ← el ojo alcanza al cuerpo tras un escalon (0 = como antes)
// ─────────────────────────────────────────────────────────────────────────────────────────────
(function () {

  var VERSION = 'v1.2';
  // MC_HW/MC_PH son `const` de app.js: se leen por la cadena de ambitos, pero no estan en window.
  // El respaldo mantiene el snippet ejecutable en pruebas headless.
  var HW = (typeof MC_HW === 'number') ? MC_HW : 0.3;   // medio ancho del jugador a escala 1
  var PH = (typeof MC_PH === 'number') ? MC_PH : 1.8;   // alto del jugador a escala 1
  var MC_T = (typeof MC_TILE === 'number') ? MC_TILE : 16;   // voxeles finos por bloque de mundo
  var ALCANCE = 0.45;                                   // cuanto se asoma el sondeo mas alla del cuerpo
  var EPS_PIE = 1 / (MC_T * 2);                         // medio voxel fino: lo justo para mirar BAJO los pies
  var GRAVEDAD = 22;                                    // la misma que app.js (mc.vel[1] -= 22*dt)
  var PASO = (typeof MC_STEP === 'number') ? MC_STEP : 0.6;   // escalon que app.js sube solo (mcMoveAxis)
  var TAU_PASO = 0.06;                                  // constante de tiempo del ojo al subir un escalon (s)

  // ── Registro: una entrada por MATERIAL ──────────────────────────────────────────────────────
  var tabla = {};       // clave ('hab:escalera') -> cfg normalizado
  var porId = [];       // cache DENSA id -> cfg. Este es el «indice de array» de Minecraft.
  var porIdLen = -1;    // longitud de mc.blockKey con la que se construyo la cache

  // La paleta solo APENDA (mcAddBlock, app.js:4358), asi que comparar la longitud basta para saber
  // si cambio. Es la misma invalidacion que usa mcXnameCache (app.js:5429).
  function reconstruirCache() {
    porId = [];
    var bk = (typeof mc !== 'undefined' && mc.blockKey) || [];
    for (var id = 1; id < bk.length; id++) {
      var cfg = tabla[bk[id]];
      if (cfg) porId[id] = cfg;
    }
    porIdLen = bk.length;
  }
  function cfgDeId(id) {
    if (!id) return null;                                // 0 = aire
    var bk = (mc && mc.blockKey) || [];
    if (porIdLen !== bk.length) reconstruirCache();
    return porId[id] || null;
  }
  // OJO: mcGetVoxel REDONDEA (app.js:6273), que no es lo que quiere una posicion continua: desde
  // x=10.6 devolveria la celda 11. Aqui se trunca, que es la celda en la que estas de verdad.
  function idEn(x, y, z) {
    x = Math.floor(x); y = Math.floor(y); z = Math.floor(z);
    if (!mc.grid || !mcInside(x, y, z)) return 0;
    return mc.grid[mcIdx(x, y, z)] || 0;
  }

  // ── Estructuras finas: la MITAD del mundo que no esta en mc.grid ─────────────────────────────
  // Un asset solo entra en la rejilla si es un 16³ MACIZO (blockLike, app.js:4006: nvox>=4096, o sea
  // hierba/roca). Cualquier cosa con forma o huecos -- una escalera de 160 voxels -- se estampa como
  // ESTRUCTURA FINA (mc.structures), con su malla propia a 1/16 de bloque y FUERA de mc.grid. Mirar
  // solo la rejilla es ver medio mundo: rayos-X lo canta («estructura · guardada · hab:escalera»).
  // Esto es mcFineBoxHit (app.js:4935) devolviendo la CLAVE en vez de un si/no, con su mismo recorte
  // por AABB (barato: las estructuras lejanas se descartan con tres comparaciones).
  function claveFinaEn(x, y, z) {
    var ests = (typeof mc !== 'undefined' && mc.structures) || null;
    if (!ests || !ests.length || typeof mcStructColl !== 'function') return null;
    var fx = Math.floor(x * MC_T), fy = Math.floor(y * MC_T), fz = Math.floor(z * MC_T);
    for (var i = 0; i < ests.length; i++) {
      var s = ests[i], g = mcStructColl(s);
      if (!g || !g.bits) continue;
      var d = g.fdim;
      var lx = fx - s.ox * MC_T; if (lx < 0 || lx >= d[0]) continue;
      var ly = fy - s.oy * MC_T; if (ly < 0 || ly >= d[1]) continue;
      var lz = fz - s.oz * MC_T; if (lz < 0 || lz >= d[2]) continue;
      if (g.bits[(ly * d[2] + lz) * d[0] + lx]) return s.key;
    }
    return null;
  }
  // Un punto del mundo -> que material hay ahi, venga de la rejilla o de una estructura fina.
  function materialEn(x, y, z) {
    var id = idEn(x, y, z);
    if (id) return { clave: (mc.blockKey && mc.blockKey[id]) || '?', cfg: cfgDeId(id), id: id, fina: false };
    var k = claveFinaEn(x, y, z);
    if (k) return { clave: k, cfg: tabla[k] || null, id: 0, fina: true };
    return null;
  }
  // Barrido hacia donde MIRA el jugador (sentido -1 = a su espalda), desde el borde del cuerpo hacia
  // fuera y en pasos de UN VOXEL FINO. No es un punto suelto a proposito: una escalera fina tiene
  // 1/16 de bloque de grosor y un unico sondeo casi nunca cae dentro. El coste es lineal con la
  // escala del jugador (no cubico como un barrido de AABB) y esta acotado.
  function barrer(sentido, filtro, y) {
    var p = mc.pos, esc = mc.scale || 1;
    var fx = -Math.sin(mc.yaw) * sentido, fz = -Math.cos(mc.yaw) * sentido;   // app.js:5061
    if (y == null) y = p[1] + PH * esc * 0.5;                                 // por defecto, el pecho
    var paso = 1 / MC_T, d0 = HW * esc;
    var n = Math.min(64, Math.ceil(ALCANCE * esc / paso));
    for (var i = 0; i <= n; i++) {
      var d = d0 + i * paso, x = p[0] + fx * d, z = p[2] + fz * d;
      var m = materialEn(x, y, z);
      if (m && (!filtro || filtro(m))) { m.fx = fx; m.fz = fz; m.x = x; m.y = y; m.z = z; return m; }
    }
    return null;
  }
  function esTrepable(m) { return !!(m.cfg && m.cfg.trepable); }

  // ¿Hay algo TREPABLE en la columna del cuerpo (de los pies a la cabeza) sobre el punto (x,z)?
  //
  // Se mira la altura ENTERA, no una o dos alturas sueltas, porque la escalera puede tener CUALQUIER
  // forma. La de verdad son dos largueros y peldanos cada 4 voxeles finos: a la altura del pecho hay
  // AIRE justo en los huecos entre peldanos, asi que sondear el pecho solo agarraba en los largueros
  // -- de ahi que solo se subiera «por los laterales» y en el centro el jugador se trabase.
  //
  // Barato pese a mirar mas: cada estructura se descarta consultando la TABLA antes de tocar su
  // geometria, asi que un mundo lleno de muebles no cuesta nada; solo se escanea lo ya trepable.
  function trepableEnColumna(x, z, y0, y1) {
    var by1 = Math.floor(y1);
    for (var by = Math.floor(y0); by <= by1; by++) {
      var id = idEn(x, by, z), cfg = cfgDeId(id);
      if (cfg && cfg.trepable) return { cfg: cfg, clave: (mc.blockKey && mc.blockKey[id]) || '?', fina: false };
    }
    var ests = (mc && mc.structures) || [];
    if (!ests.length || typeof mcStructColl !== 'function') return null;
    var fx = Math.floor(x * MC_T), fz = Math.floor(z * MC_T);
    var fy0 = Math.floor(y0 * MC_T), fy1 = Math.floor(y1 * MC_T);
    for (var i = 0; i < ests.length; i++) {
      var s = ests[i], c = tabla[s.key];
      if (!c || !c.trepable) continue;                    // descarte por tabla, sin mirar la malla
      var g = mcStructColl(s); if (!g || !g.bits) continue;
      var d = g.fdim;
      var lx = fx - s.ox * MC_T; if (lx < 0 || lx >= d[0]) continue;
      var lz = fz - s.oz * MC_T; if (lz < 0 || lz >= d[2]) continue;
      var ly0 = Math.max(fy0 - s.oy * MC_T, 0), ly1 = Math.min(fy1 - s.oy * MC_T, d[1] - 1);
      for (var ly = ly0; ly <= ly1; ly++)
        if (g.bits[(ly * d[2] + lz) * d[0] + lx]) return { cfg: c, clave: s.key, fina: true };
    }
    return null;
  }
  // Barrido del agarre: hacia donde se mira, del borde del cuerpo hacia fuera, mirando en cada paso
  // la columna ENTERA del cuerpo. Los pies mandan en el remate: se trepa hasta que los pies llegan al
  // final de la escalera (quedarse 0,9 por debajo seria mas de lo que sube el auto-escalon —
  // MC_STEP=0,6, app.js:4911 — y no se podria coronar).
  function barrerAgarre() {
    var p = mc.pos, esc = mc.scale || 1;
    var fx = -Math.sin(mc.yaw), fz = -Math.cos(mc.yaw);
    var y0 = p[1] + 0.05 * esc, y1 = p[1] + PH * esc * 0.95;
    var paso = 1 / MC_T, d0 = HW * esc, n = Math.min(64, Math.ceil(ALCANCE * esc / paso));
    for (var i = 0; i <= n; i++) {
      var d = d0 + i * paso;
      var m = trepableEnColumna(p[0] + fx * d, p[2] + fz * d, y0, y1);
      if (m) { m.fx = fx; m.fz = fz; return m; }
    }
    return null;
  }

  // ── Avisos acotados (§22: nada de una linea por frame) ──────────────────────────────────────
  var avisos = [], vistos = {};
  function avisar(msg) {
    if (vistos[msg]) { vistos[msg]++; return; }           // el mismo fallo no se repite en consola
    vistos[msg] = 1;
    avisos.push(msg);
    if (avisos.length > 20) avisos.shift();
    console.warn('game.bloques · ' + msg + ' (no se repetirá; míralo con game.bloques.avisos())');
  }

  // ── Alta/baja de comportamientos ────────────────────────────────────────────────────────────
  function clavesConocidas() {
    var out = [], i;
    var bk = (mc && mc.blockKey) || [];
    for (i = 1; i < bk.length; i++) if (bk[i] && out.indexOf(bk[i]) < 0) out.push(bk[i]);
    var cat = (mc && mc.catalog) || [];
    for (i = 0; i < cat.length; i++) if (cat[i] && cat[i].key && out.indexOf(cat[i].key) < 0) out.push(cat[i].key);
    var ests = (mc && mc.structures) || [];   // lo ya estampado, aunque no este en la galeria abierta
    for (i = 0; i < ests.length; i++) if (ests[i] && ests[i].key && out.indexOf(ests[i].key) < 0) out.push(ests[i].key);
    return out;
  }
  // Nombre corto de un material: sin namespace, sin carpeta y sin extension.
  //   hab:escalera                 -> escalera
  //   asset:assets/arena.vox.json  -> arena
  function nombreCorto(k) {
    var s = String(k), i = s.indexOf(':');
    if (i >= 0) s = s.slice(i + 1);
    i = s.lastIndexOf('/');
    if (i >= 0) s = s.slice(i + 1);
    return s.replace(/\.vox\.json$/i, '').replace(/\.json$/i, '').toLowerCase();
  }
  // Nadie deberia tener que escribir "asset:assets/arena.vox.json" para decir «arena». Se admite el
  // nombre corto siempre que señale a UN solo material; si es ambiguo NO se elige por el dueño, se
  // plantan los candidatos. La clave que se registra es siempre la LARGA, que es la que traen los
  // voxels del mundo.
  function resolver(clave) {
    var conocidas = clavesConocidas();
    if (!conocidas.length) return { clave: clave };        // Mundo sin abrir: no hay contra que validar
    if (conocidas.indexOf(clave) >= 0) return { clave: clave };
    var corto = nombreCorto(clave);
    var cand = conocidas.filter(function (k) { return nombreCorto(k) === corto; });
    if (cand.length === 1) return { clave: cand[0], alias: true };
    if (cand.length > 1) return { error: '"' + clave + '" vale para ' + cand.length + ' materiales ('
      + cand.join(', ') + '). Escribe la clave entera.' };
    var pistas = conocidas.filter(function (k) { return k.indexOf(clave) >= 0; });
    return { error: 'no existe el material "' + clave + '". '
      + (pistas.length ? '¿Querías ' + pistas.map(function (p) { return '"' + p + '"'; }).join(' o ') + '?'
                       : 'Ponte encima y usa game.bloques.info() para ver su clave exacta.') };
  }
  function num(v, def) { v = parseFloat(v); return isFinite(v) ? v : def; }

  function define(clave, cfg) {
    clave = String(clave == null ? '' : clave).trim();
    if (!clave) { console.warn('game.bloques.define: falta la clave del material.'); return null; }
    if (!cfg || typeof cfg !== 'object') {
      console.warn('game.bloques.define("' + clave + '"): el 2º argumento debe ser un objeto de opciones.');
      return null;
    }
    // Se admite el nombre corto ('arena', 'escalera') si no es ambiguo. Si la paleta aun no esta
    // construida (Mundo sin abrir) no se valida: no hay contra que comparar.
    var res = resolver(clave);
    if (res.error) { console.warn('game.bloques.define: ' + res.error); return null; }
    if (res.alias) console.log('game.bloques.define: "' + clave + '" → ' + res.clave);
    clave = res.clave;
    // Trampolin: 'impulso' es la VELOCIDAD VERTICAL inicial en u/s, la misma magnitud que el salto de
    // app.js (8.0). 'altura' es azucar para quien piensa en bloques: v = sqrt(2·g·h) con g=22.
    var imp = Math.abs(num(cfg.impulso, 0));
    if (!imp && num(cfg.altura, 0) > 0) imp = Math.sqrt(2 * GRAVEDAD * Math.abs(num(cfg.altura, 0)));
    var norm = {
      clave: clave,
      trepable: !!cfg.trepable,
      subida: Math.abs(num(cfg.subida, 4)),               // u/s al avanzar contra ella
      bajada: Math.abs(num(cfg.bajada, 5)),               // u/s al retroceder
      impulso: imp,                                       // u/s verticales al pisarla (0 = no es trampolin)
      alPisar: (typeof cfg.alPisar === 'function') ? cfg.alPisar : null,
      nota: String(cfg.nota || '')
    };
    if (!norm.trepable && !norm.alPisar && !norm.impulso) {
      console.warn('game.bloques.define("' + clave + '"): sin trepable, impulso ni alPisar no hace nada.');
      return null;
    }
    // La inercia horizontal del trampolin la conserva app.js SOLO con air-control puesto: si esta apagado,
    // la velocidad horizontal se reescribe cada frame desde las teclas y al soltarlas te paras en el aire.
    if (norm.impulso && typeof mc !== 'undefined' && mc.airControl === false) {
      console.warn('game.bloques.define("' + clave + '"): game.airControl esta APAGADO, asi que el impulso '
        + 'no conservara la inercia horizontal (te pararas en el aire al soltar las teclas).');
    }
    tabla[clave] = norm;
    reconstruirCache();
    return norm;
  }
  function quitar(clave) {
    clave = String(clave == null ? '' : clave).trim();
    if (!tabla[clave]) {                                   // el mismo nombre corto que admite define()
      var corto = nombreCorto(clave);
      var cand = Object.keys(tabla).filter(function (k) { return nombreCorto(k) === corto; });
      if (cand.length === 1) clave = cand[0];
    }
    if (!tabla[clave]) { console.warn('game.bloques.quitar: "' + clave + '" no tenía comportamiento.'); return false; }
    delete tabla[clave];
    reconstruirCache();
    return true;
  }

  // ── Trepar: UNA celda sondeada, coste fijo ──────────────────────────────────────────────────
  // No se barre el AABB del jugador a proposito: ese barrido crece con game.playerScale AL CUBO y
  // es exactamente lo que ya hundio los fps con la colision fina. Aqui es una lectura de rejilla.
  //
  // Va en DOS mitades, una a cada lado del mcUpdate original, y no es un capricho. Anular la
  // gravedad DESPUES de que el frame la haya aplicado deja una perdida de 22*dt^2 por frame: a 60
  // fps son 0,37 u/s (de 4 subes 3,64) y a 30 fps el DOBLE, o sea que la escalera treparia mas
  // despacio en un ordenador lento. Sondeando antes y deshaciendo la caida despues, la velocidad es
  // exactamente la que dice el define, pasen los fps que pasen.
  function sondearAgarre() {
    if (!mc.grid || !mc.pos) return null;                 // fuera del Mundo no hay nada que sondear
    var k = mc.keys || {};
    // Salida de emergencia. Con el agarre puesto mc.onGround queda en false, asi que el salto de
    // app.js:5085 (exige onGround) no dispararia NUNCA: sin esto, colgado de una escalera solo se
    // puede soltar la tecla. El espacio suelta el agarre y da el impulso a mano, una vez por
    // pulsacion (si no, mantenerlo pulsado seria volar).
    if (k[' ']) {
      if (!saltoPrev && agarradoPrev) mc.vel[1] = 8.0 * Math.sqrt(mc.scale || 1);   // mismo salto que app.js:5085
      saltoPrev = true;
      return null;
    }
    saltoPrev = false;
    var adelante = !!k['w'], atras = !!k['s'];
    if (adelante && atras) return null;                   // las dos a la vez se anulan
    // Soltar la tecla NO suelta la escalera: uno se queda COLGADO donde estaba, como en Minecraft.
    // Caerse al dejar de pulsar obliga a subirlo todo de una tirada y convierte cualquier pausa en
    // una caida desde lo alto. Solo se sostiene a quien YA venia agarrado: de pie en el suelo junto
    // a una escalera manda la fisica normal, y pasar al lado no engancha a nadie.
    if (!adelante && !atras && !agarradoPrev) return null;
    // Se barre SIEMPRE hacia donde MIRA el jugador, tanto para subir como para bajar: la escalera
    // es solida y uno la tiene delante en los dos casos. Sondear hacia atras con S miraria la celda
    // OPUESTA a la escalera (aire) y la bajada seria en realidad una caida libre.
    // Se busca el primer material TREPABLE, no el primero a secas: asi un adorno fino entre el
    // jugador y la escalera no impide agarrarse.
    var m = barrerAgarre();
    if (!m) return null;
    var esc = mc.scale || 1;
    // Velocidad ∝ √escala, igual que la marcha (app.js:5059) y el salto (app.js:5085).
    var v = adelante ? m.cfg.subida : atras ? -m.cfg.bajada : 0;   // sin tecla: quieto, pero agarrado
    return { cfg: m.cfg, clave: m.clave, v: v * Math.sqrt(esc), fx: m.fx, fz: m.fz };
  }
  function aplicarTrepado(agarre, antes, dt) {
    var p = mc.pos;
    // Si el original SUBIO (el auto-escalon de mcMoveAxis coronando la escalera) se respeta; si
    // BAJO (gravedad) se deshace: agarrado a una escalera no se cae.
    var base = Math.max(antes[1], p[1]);
    // Colgado y quieto, pero la fisica normal ha encontrado suelo: se suelta el agarre en vez de
    // dejar al jugador flotando a un pelo del piso sin poder saltar. Lo dice el original, sin sondeo.
    if (agarre.v === 0 && mc.onGround) return null;
    var ny = base + agarre.v * dt;
    if (ny < 0) ny = 0;
    // Solo se sube/baja si ahi cabe el cuerpo: nunca se trepa dentro de un techo ni se atraviesa el suelo.
    if (mcCollides(p[0], ny, p[2])) {
      // Bajando y con algo debajo = se acabo la escalera. Se suelta el agarre ENTERO (fisica normal
      // y sin tocar el horizontal), asi que con S se aterriza y se sigue andando hacia atras. Anular
      // el retroceso tambien aqui era lo que dejaba al jugador «pegado» sin poder soltarse.
      if (agarre.v < 0) return null;
      p[1] = base;
    } else {
      p[1] = ny;
      // COLGADO y bajando: el original ya ha andado hacia atras y despegaria de la escalera en tres
      // frames. Se anula SOLO la componente que se aleja de ella; lo lateral se respeta (soltarse de
      // lado es una salida). En cuanto haya suelo bajo los pies, el caso de arriba devuelve el mando.
      if (agarre.v < 0) {
        var proy = (p[0] - antes[0]) * agarre.fx + (p[2] - antes[2]) * agarre.fz;
        if (proy < 0) { p[0] -= proy * agarre.fx; p[2] -= proy * agarre.fz; }
      }
    }
    mc.onGround = false;
    mc.vel[1] = 0;                                        // agarrado: la gravedad no se acumula
    return agarre.cfg;
  }

  // ── Pisar: por EVENTO (flanco), no por sondeo ───────────────────────────────────────────────
  // Igual que onEntityCollision de Minecraft: se dispara en el FLANCO, cuando cambia lo que hay bajo
  // los pies, asi que quedarse quieto encima no vuelve a lanzarlo. Coste por frame: una lectura de
  // rejilla + una comparacion de cadenas.
  //
  // La identidad NO es solo la celda: es celda + CLAVE de lo que se pisa. Una placa de presion es
  // una estructura de 1/16 de alto, asi que caer sobre ella desde el aire no cambia la celda de
  // debajo (ya era esa) y el flanco por celda se lo perdia entero.
  var pisadas = {};
  var saltoPrev = false, agarradoPrev = false;   // para el salto de una pulsacion y la salida de emergencia
  function pieEn() {
    if (!mc.grid || !mc.pos) return null;
    var p = mc.pos, y = p[1] - EPS_PIE;                   // medio voxel fino BAJO los pies
    var m = materialEn(p[0], y, p[2]);
    var celda = Math.floor(p[0]) + ',' + Math.floor(y) + ',' + Math.floor(p[2]);
    return { celda: celda, id: celda + '|' + (m ? m.clave : ''), m: m };
  }
  function pisar(antes) {
    var ahora = pieEn();
    if (!ahora || !ahora.m || !ahora.m.cfg) return null;
    if (!ahora.m.cfg.alPisar && !ahora.m.cfg.impulso) return null;
    if (antes && antes.id === ahora.id) return null;      // nada ha cambiado bajo los pies
    var c = ahora.celda.split(','), cfg = ahora.m.cfg;
    pisadas[ahora.id] = (pisadas[ahora.id] || 0) + 1;
    // Trampolin estilo Quake. Es EXACTAMENTE el salto de app.js:5090 —velocidad vertical + onGround=false—
    // pero con la fuerza que diga el material y sin pulsar espacio. La inercia horizontal NO se toca: con
    // air-control puesto app.js conserva vel[0]/vel[2] intactos mientras no haya suelo, asi que sales
    // despedido con la velocidad que llevabas al pisar. El ∝√escala es el mismo del salto y de la marcha.
    if (cfg.impulso) {
      mc.vel[1] = cfg.impulso * Math.sqrt(mc.scale || 1);
      mc.onGround = false;                                // sin esto el frame siguiente te vuelve a clavar al suelo
    }
    if (!cfg.alPisar) return cfg;
    try {
      cfg.alPisar({ x: +c[0], y: +c[1], z: +c[2], clave: ahora.m.clave, cfg: cfg,
                    veces: pisadas[ahora.id], pos: mc.pos });
    } catch (e) {
      avisar('el alPisar de ' + ahora.m.clave + ' lanzó: ' + (e && e.message ? e.message : e));
    }
    return cfg;
  }

  // ── Diagnostico ─────────────────────────────────────────────────────────────────────────────
  function resumen(cfg) {
    var partes = [];
    if (cfg.trepable) partes.push('trepable ↑' + cfg.subida + ' ↓' + cfg.bajada);
    // La altura que alcanza es h = v²/2g: lo util para colocar la plataforma de destino.
    if (cfg.impulso) partes.push('impulso ↑' + (Math.round(cfg.impulso * 10) / 10)
      + ' (~' + (Math.round(cfg.impulso * cfg.impulso / (2 * GRAVEDAD) * 10) / 10) + ' bloques)');
    if (cfg.alPisar) partes.push('alPisar');
    return partes.join(' + ');
  }
  function ficha(donde, m, x, y, z) {
    return { donde: donde, celda: Math.floor(x) + ',' + Math.floor(y) + ',' + Math.floor(z),
             clave: m ? m.clave : '(aire)',
             tipo: m ? (m.fina ? 'estructura' : 'bloque') : '—',
             comportamiento: (m && m.cfg) ? resumen(m.cfg) : '—' };
  }
  // La clave EXACTA es el dato que hace falta para define(): 'hab:escalera', no 'escalera'.
  // Delante/detras usan el MISMO barrido que el trepado, asi que lo que dice info() es literalmente
  // lo que ve el agarre: si aqui sale la escalera, subir tiene que funcionar.
  function info() {
    if (!mc.grid) { console.log('game.bloques.info(): abre el Mundo (🌍) primero.'); return []; }
    var p = mc.pos, esc = mc.scale || 1, yPecho = p[1] + PH * esc * 0.5;
    var pies = materialEn(p[0], p[1] - EPS_PIE, p[2]);
    var del = barrer(1, null), det = barrer(-1, null);
    var filas = [
      ficha('bajo los pies', pies, p[0], p[1] - EPS_PIE, p[2]),
      ficha('delante (pecho)', del, del ? del.x : p[0], yPecho, del ? del.z : p[2]),
      ficha('detrás (pecho)', det, det ? det.x : p[0], yPecho, det ? det.z : p[2])
    ];
    if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }
  function lista() {
    var filas = Object.keys(tabla).map(function (k) {
      return { clave: k, comportamiento: resumen(tabla[k]), nota: tabla[k].nota || '' };
    });
    if (!filas.length) console.log('game.bloques: ningún material tiene comportamiento todavía.');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }

  // ── Subida suave de escalones: el CUERPO da el salto, el OJO lo alcanza ──────────────────────
  // app.js sube los escalones de golpe (mcMoveAxis: p[1] += h dentro del mismo frame), asi que al
  // andar por una escalera de 8 voxels la camara teletransporta y+0,5 de una vez y se ve a saltos.
  // Es lo mismo que hace Minecraft, y Minecraft lo tapa igual que aqui: la fisica NO se toca (el
  // juego sigue igual de firme, misma colision y mismo alcance de escalon), solo se PINTA al jugador
  // un poco mas abajo y ese retraso se consume en ~0,1 s.
  //
  // Como el ojo se calcula en seis sitios distintos de app.js a partir de mc.pos[1], el desfase se
  // aplica sobre mc.pos[1] al SALIR del frame y se deshace al ENTRAR en el siguiente: entre medias
  // solo hay dibujado, y toda la fisica corre siempre sobre la y de verdad.
  //
  // El estado vive en mc (no en un closure) a proposito: si se reejecuta el snippet, el envoltorio
  // nuevo hereda el desfase que dejo el viejo en vez de dejar al jugador medio bloque hundido.
  function restaurarPaso() {
    var d = mc._pasoDesfase || 0;
    if (!d) return;
    // Si la y no es la que dejamos pintada, es que alguien movio al jugador por su cuenta
    // (game.tp, un respawn, un alPisar…): ese desfase ya no significa nada y se tira.
    // Se repone la y GUARDADA, no pos[1]+d: sumar y restar el desfase no da exactamente el mismo
    // float, y ese pelo de diferencia acabaria en la colision. Asi la fisica es idéntica al bit.
    if (mc._pasoY === mc.pos[1]) mc.pos[1] = mc._pasoReal; else mc._pasoDesfase = 0;
  }

  // El escalon se mide DONDE SE DA: dentro de mcMoveAxis, cuyo unico efecto sobre la y es el
  // `p[1] += h` del auto-escalon (app.js:4919), y cuyos dos unicos llamantes son las dos lineas
  // horizontales de mcUpdate. Deducirlo al final del frame comparando la y NO funciona, y fue el
  // primer intento: en app.js la gravedad va ANTES del horizontal, asi que el frame del escalon
  // termina con vel[1]=0 y `ny === p[1]`, no choca y deja **onGround = false** (app.js:5097). Una
  // guarda que pidiese «estar en el suelo» se apaga justo en el unico frame que hay que suavizar —
  // el dueño no notaba ninguna diferencia entre pasoSuave(0) y pasoSuave(1000). Midiendo aqui no hay
  // heuristica: saltar y trepar no pasan por mcMoveAxis, asi que no se cuelan solos.
  function envolverMoveAxis() {
    if (typeof mcMoveAxis !== 'function') return false;
    var orig = mcMoveAxis._paso ? mcMoveAxis._orig : mcMoveAxis;
    var env = function (ai, target) {
      var y0 = mc.pos[1];
      orig(ai, target);
      var d = mc.pos[1] - y0;
      if (d > 0) mc._pasoSubido = (mc._pasoSubido || 0) + d;
    };
    env._paso = VERSION;
    env._orig = orig;
    window.mcMoveAxis = env;
    return true;
  }

  function suavizarPaso(dt) {
    var d = mc._pasoDesfase || 0;
    var subido = mc._pasoSubido || 0;                   // lo que el auto-escalon levanto este frame
    mc._pasoSubido = 0;
    var tope = PASO * (mc.scale || 1);
    if (TAU_PASO > 0) {
      d += subido;                                      // el ojo se queda donde estaba
      d *= Math.exp(-dt / TAU_PASO);                    // independiente de los fps
      if (d > tope) d = tope;                           // nunca mas de un escalon por detras
      if (d < 1 / 512) d = 0;                           // menos de eso no se ve: se cierra en seco
    } else {
      d = 0;
    }
    mc._pasoDesfase = d;
    if (d) { mc._pasoReal = mc.pos[1]; mc.pos[1] -= d; mc._pasoY = mc.pos[1]; }
  }

  // ── Instalacion: un unico envoltorio, SIEMPRE el de esta ejecucion ───────────────────────────
  // No apilar envoltorios sigue siendo obligatorio (apilarlos duplicaria la velocidad de trepado en
  // cada pasada), pero NO basta con no reinstalar: el envoltorio viejo se quedaba con SUS closures, y
  // sobre todo con SU tabla de materiales. Reejecutar el snippet creaba una tabla nueva que la fisica
  // no leia jamas, asi que todo lo definido a partir de ahi salia en lista()/info() y no hacia
  // absolutamente nada en el mundo (el dueño lo vio con un trampolin: la consola decia «impulso ↑12»
  // y el bloque no lanzaba). Lo correcto es DESENVOLVER el viejo por su _orig y volver a envolver.
  var previo = (typeof mcUpdate === 'function' && mcUpdate._bloques) ? mcUpdate : null;
  var yaEstaba = !!previo;
  if (typeof mcUpdate !== 'function') {
    console.warn('game.bloques: no encuentro mcUpdate; ¿es esta la pestaña del Mundo?');
  } else {
    var orig = previo ? previo._orig : mcUpdate;
    var envuelto = function (dt) {
      restaurarPaso();                                  // la fisica SIEMPRE arranca en la y de verdad
      var pieAntes = pieEn();
      var agarre = sondearAgarre();                       // ANTES de mover: la gravedad aun no se aplico
      var posAntes = mc.pos ? [mc.pos[0], mc.pos[1], mc.pos[2]] : null;
      orig(dt);                                           // la fisica de siempre, intacta
      if (!mc.grid) return;
      agarradoPrev = !!((agarre && posAntes) ? aplicarTrepado(agarre, posAntes, dt) : null);
      pisar(pieAntes);
      suavizarPaso(dt);                                 // lo ultimo: a partir de aqui solo se dibuja
    };
    envuelto._bloques = VERSION;
    envuelto._orig = orig;
    window.mcUpdate = envuelto;
    envolverMoveAxis();                                   // el segundo (y ultimo) enganche: mide el escalon
  }

  var anterior = (typeof game !== 'undefined' && game.bloques) || null;   // antes de pisarlo
  if (previo && anterior && typeof anterior.pasoSuave === 'function') {
    var tauViejo = anterior.pasoSuave();                 // lo que el dueño hubiera ajustado a mano
    if (typeof tauViejo === 'number' && isFinite(tauViejo)) TAU_PASO = tauViejo;
  }

  game.bloques = {
    version: VERSION,
    define: define, quitar: quitar, lista: lista, info: info,
    avisos: function () { return avisos.slice(); },
    // Cuanto tarda el ojo en alcanzar al cuerpo tras un escalon, en segundos. 0 = como antes
    // (salto instantaneo). Por encima de ~0,15 se nota flotante. Sin argumento, lo consulta.
    pasoSuave: function (tau) {
      if (tau === undefined) return TAU_PASO;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.pasoSuave: dame segundos, 0 para desactivar.'); return TAU_PASO; }
      TAU_PASO = tau;
      if (!tau && mc._pasoDesfase) { restaurarPaso(); mc._pasoDesfase = 0; }   // se apaga sin dejar al ojo hundido
      console.log('game.bloques: subida de escalon ' + (tau ? 'suavizada en ' + tau + ' s' : 'instantánea (como antes)'));
      return TAU_PASO;
    },
    _tabla: tabla,
    _porId: function () { return porId.slice(); }         // para inspeccionar la cache densa
  };

  // ── Comportamientos por defecto de este mundo ────────────────────────────────────────────────
  define('hab:escalera', { trepable: true, subida: 4, bajada: 5, nota: 'Avanza contra ella para subir, retrocede para bajar.' });
  define("asset:assets/diana.vox.json", { impulso: 24 });

  // Lo que ya hubiera definido el dueño sobrevive a reejecutar el snippet: los cfg guardados ya estan
  // normalizados y define() los vuelve a normalizar con el codigo de ahora, asi que valen aunque la
  // version anterior tuviera otra forma. Van DESPUES de los de fabrica para que ganen los suyos.
  var heredado = (previo && anterior && anterior._tabla) || null;
  if (heredado) {
    var claves = Object.keys(heredado);
    claves.forEach(function (k) { define(k, heredado[k]); });
    if (claves.length) console.log('game.bloques: heredados ' + claves.length + ' material(es) de la ejecución anterior.');
  }

  console.log('game.bloques ' + VERSION + ' · ' + Object.keys(tabla).length + ' material(es) con comportamiento'
    + (yaEstaba ? ' (envoltorio REINSTALADO: la física ahora lee esta tabla)' : '')
    + '. game.bloques.lista() / .info()');

})();
